{"file_path":"src/errors.js","content":"/**
 * Error classes carrying the exit code that `cli.js` reports for them.
 */

export class CliError extends Error {
  constructor(message, exitCode) {
    super(message)
    this.exitCode = exitCode
  }
}

export class UsageError extends CliError {
  constructor(message) {
    super(message, 2)
  }
}

export class CycleError extends CliError {
  constructor(cycleNames) {
    super(`cycle: ${cycleNames.join(' -> ')}`, 3)
    this.cycleNames = cycleNames
  }
}
"}

