{"file_path":"src/parser.js","content":"/**
 * Parses build-graph text into a map of task name to `{ cost, deps }`,
 * where `deps` is a `Set` of dependency names. Throws `UsageError` for any
 * malformed input.
 */

import { UsageError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const depEntries = [] // { target, deps: string[], line }

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new UsageError(`line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new UsageError(`line ${lineNumber}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new UsageError(`line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new UsageError(`line ${lineNumber}: task ${name} is declared twice`)
      }
      tasks.set(name, { cost: parseInt(costStr, 10), deps: new Set() })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new UsageError(`line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      const [, target, ...deps] = words
      for (const name of [target, ...deps]) {
        if (!NAME_RE.test(name)) {
          throw new UsageError(`line ${lineNumber}: invalid task name ${name}`)
        }
      }
      depEntries.push({ target, deps, line: lineNumber })
    } else {
      throw new UsageError(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  for (const { target, deps } of depEntries) {
    for (const name of [target, ...deps]) {
      if (!tasks.has(name)) {
        throw new UsageError(`unknown task ${name}`)
      }
    }
  }

  for (const { target, deps } of depEntries) {
    const entry = tasks.get(target)
    for (const dep of deps) entry.deps.add(dep)
  }

  return tasks
}
"}

