{"file_path":"src/graph.js","content":"/**
 * Graph-level computations shared by every mode: cycle detection, wave
 * depths, and unlimited-worker start/finish times.
 */

import { CycleError } from './errors.js'

/**
 * Walks the graph depth-first from each task in ascending name order,
 * following each task's dependencies in ascending name order, and throws
 * `CycleError` for the first cycle such a search re-enters.
 */
export function detectCycle(tasks) {
  const state = new Map() // name -> 'visiting' | 'done'
  const stack = []

  function visit(name) {
    const status = state.get(name)
    if (status === 'done') return
    if (status === 'visiting') {
      const start = stack.indexOf(name)
      const cycle = stack.slice(start)
      cycle.push(name)
      throw new CycleError(cycle)
    }
    state.set(name, 'visiting')
    stack.push(name)
    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) visit(dep)
    stack.pop()
    state.set(name, 'done')
  }

  for (const name of [...tasks.keys()].sort()) {
    visit(name)
  }
}

/**
 * Computes, for every task, the wave depth, start time, and finish time
 * described for `waves` and `explain`: depth is the longest dependency
 * chain length, start is the greatest dependency finish (or 0), and finish
 * is start plus cost.
 */
export function computeTimings(tasks) {
  const timing = new Map() // name -> { start, finish, depth }

  function compute(name) {
    const cached = timing.get(name)
    if (cached) return cached
    const task = tasks.get(name)
    let start = 0
    let depth = 0
    for (const dep of task.deps) {
      const depTiming = compute(dep)
      if (depTiming.finish > start) start = depTiming.finish
      if (depTiming.depth + 1 > depth) depth = depTiming.depth + 1
    }
    const result = { start, finish: start + task.cost, depth }
    timing.set(name, result)
    return result
  }

  for (const name of tasks.keys()) compute(name)
  return timing
}
"}

