{"file_path":"src/pack.js","content":"/**
 * Simulates the build graph on a fixed number of workers, as described for
 * the `pack` mode: at every instant, free workers claim the highest-priority
 * ready task (ties broken by ascending name), and time advances to the next
 * instant a worker frees up when nothing more can start.
 */

/**
 * Priority is the cost of the longest chain starting at a task and running
 * forward through its dependents down to a task nothing depends on.
 */
function computePriorities(tasks) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, task] of tasks) {
    for (const dep of task.deps) dependents.get(dep).push(name)
  }

  const priority = new Map()
  function compute(name) {
    const cached = priority.get(name)
    if (cached !== undefined) return cached
    const task = tasks.get(name)
    let best = 0
    for (const child of dependents.get(name)) {
      const childPriority = compute(child)
      if (childPriority > best) best = childPriority
    }
    const result = task.cost + best
    priority.set(name, result)
    return result
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

export function packWorkers(tasks, workerCount) {
  const priority = computePriorities(tasks)
  const workerFree = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])
  const finishOf = new Map()
  const remaining = new Set(tasks.keys())

  let time = 0
  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false
      const freeWorkers = []
      for (let i = 0; i < workerCount; i++) {
        if (workerFree[i] <= time) freeWorkers.push(i)
      }
      if (freeWorkers.length === 0) break

      const ready = []
      for (const name of remaining) {
        const task = tasks.get(name)
        let isReady = true
        for (const dep of task.deps) {
          if (!finishOf.has(dep) || finishOf.get(dep) > time) {
            isReady = false
            break
          }
        }
        if (isReady) ready.push(name)
      }
      if (ready.length === 0) break

      ready.sort((a, b) => priority.get(b) - priority.get(a) || (a < b ? -1 : a > b ? 1 : 0))
      const chosen = ready[0]
      const workerIndex = freeWorkers[0]
      const task = tasks.get(chosen)
      const finish = time + task.cost
      workerFree[workerIndex] = finish
      workerLog[workerIndex].push({ name: chosen, start: time, finish })
      finishOf.set(chosen, finish)
      remaining.delete(chosen)
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (const free of workerFree) {
      if (free > time && free < next) next = free
    }
    time = next
  }

  return { workerLog, makespan: finishOf.size > 0 ? Math.max(...finishOf.values()) : 0 }
}
"}

